package com.example.billing.service;
import static com.example.billing.api.Contracts.*;import com.example.billing.domain.*;import com.example.billing.persistence.Repositories.*;import java.time.*;import java.util.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class UsageService {private final UsageRecordRepository usage;private final SubscriptionRepository subscriptions;private final KeyedLock locks;public UsageService(UsageRecordRepository u,SubscriptionRepository s,KeyedLock l){usage=u;subscriptions=s;locks=l;}public UsageRecordResponse report(ReportUsageRequest r,String key){key=CatalogService.req(key);var metric=CatalogService.req(r.metricName());if(r.quantity()==null||r.quantity().signum()<0)throw new IllegalArgumentException("Quantity cannot be negative.");try(var ignored=locks.acquire("usage-report:"+key)){var old=usage.findByIdempotencyKey(key).orElse(null);if(old!=null)return UsageRecordResponse.from(old);var sub=subscriptions.findById(r.subscriptionId()).orElseThrow(()->new IllegalStateException("Subscription does not exist."));var x=new UsageRecord();x.id=UUID.randomUUID();x.customerId=sub.customerId;x.subscriptionId=sub.id;x.metricName=metric;x.quantity=r.quantity();x.timestamp=r.timestamp();x.idempotencyKey=key;try{return UsageRecordResponse.from(usage.saveAndFlush(x));}catch(DataIntegrityViolationException e){return usage.findByIdempotencyKey(key).map(UsageRecordResponse::from).orElseThrow(()->e);}}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException(e);}}@Transactional(readOnly=true)public List<UsageRecordResponse> list(UUID id,OffsetDateTime s,OffsetDateTime e){return usage.findBySubscriptionIdAndTimestampGreaterThanEqualAndTimestampLessThanOrderByTimestampAscIdAsc(id,s,e).stream().map(UsageRecordResponse::from).toList();}}
